import{_ as t,o as n,c as a,a5 as i}from"./chunks/framework.CsGesDJn.js";const l=JSON.parse('{"title":"Agency Subscription — Spec entrypoint","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-subscription/spec.md","filePath":"feature/agency-subscription/spec.md"}'),r={name:"feature/agency-subscription/spec.md"};function o(c,e,s,h,p,u){return n(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="agency-subscription-—-spec-entrypoint" tabindex="-1">Agency Subscription — Spec entrypoint <a class="header-anchor" href="#agency-subscription-—-spec-entrypoint" aria-label="Permalink to &quot;Agency Subscription — Spec entrypoint&quot;">​</a></h1><h2 id="quyet-đinh-storage-đa-chot-—-br17–br22-repository" tabindex="-1">Quyết định storage đã chốt — BR17–BR22 Repository <a class="header-anchor" href="#quyet-đinh-storage-đa-chot-—-br17–br22-repository" aria-label="Permalink to &quot;Quyết định storage đã chốt — BR17–BR22 Repository&quot;">​</a></h2><p>BASIC miễn phí <strong>20 GiB/Agency = 21,474,836,480 bytes</strong>, dùng chung mọi workspace. Gói trả phí ACTIVE dùng tổng <code>plan.storageQuotaBytes</code> từ catalog, không cộng thêm 20 GiB. Khi hết hạn, quota về BASIC; giữ quyền read/preview/download và restore theo ACL. Trash đã tính usedBytes nên restore không tăng usage và không bị chặn vì quota. Chỉ chặn tạo upload/derivative/watermark khi không còn chỗ; soft delete chưa giải phóng dung lượng, purge binary thành công mới giảm. Upload đồng thời phải giữ chỗ nguyên tử theo Agency; release reservation khi fail/expire phải idempotent, không dùng Redis làm ledger. OWNER được xem aggregate usedBytes/quotaBytes và breakdown workspace của Agency mình; không có quyền đọc nội dung file ngầm nếu thiếu membership vận hành. Xem <a href="./../../../../tuan-research/REPOSITORY_SPEC.html">BR01–BR25 Repository</a>. Đây là sửa đặc tả; chưa thay catalog/migration/dữ liệu production.</p><h2 id="nguon-va-pham-vi-hien-huu" tabindex="-1">Nguồn và phạm vi hiện hữu <a class="header-anchor" href="#nguon-va-pham-vi-hien-huu" aria-label="Permalink to &quot;Nguồn và phạm vi hiện hữu&quot;">​</a></h2><p>Nguồn nghiệp vụ duy nhất: <a href="./../../../../tuan-research/spec/agency-subscription-spec.html">agency-subscription-spec.md v2</a>, ngày 20/10/2026. Người dùng chọn vị trí này cho spec; file entrypoint giúp bộ spec → plan → task → test tuân layout project mà không sao chép nghiệp vụ.</p><p>Phạm vi: FR 3.9.1, 3.9.3–3.9.7; FR 3.9.2 Downgrade/Cancel hoãn. Giữ expiry/renewal/recovery. Đọc spec đầy đủ trước thực thi, cùng <a href="./../../../../tuan-research/subscription_acid_implementation_rules.html">ACID rules</a>.</p><p>UI bổ sung theo yêu cầu feature workflow: toàn bộ text mới đi qua namespace subscription. Key groups: agency.label, agency.select, plans.basic/plus/enterprise, plans.current, plans.upgrade, checkout.amount/period/credits/expiry/submit, payment.pending/fulfilled/reviewRequired/failed/expired/retry, history.title/empty/receipt/invoiceUnavailable, credits.available/reserved/purchased/expiring/usage, budget.cap/unlimited/blocked/save/conflict, recovery.title/workspaces/members/storage/clientLimit, errors.insufficientCredits/workspaceCap/creatorCap/quota/notConfigured/forbidden. Thêm exact leaf keys phát sinh đồng thời VI/EN; không hardcode JSX. Reuse existing equivalent keys nếu có, test key parity. Light/dark dùng theme tokens hiện có; không tạo palette mới. Tất cả keyboard focus, contrast và mobile layout được nghiệm thu tại task 10.</p>',7)])])}const d=t(r,[["render",o]]);export{l as __pageData,d as default};
